$count = 0;
foreach ($posts as $i => $post) {
    // Check if slug already exists
    $stmt = blog_db_query("SELECT id FROM blog_posts WHERE slug = :slug", ['slug' => $post['slug']]);
    if ($stmt->fetch()) {
        echo "Skipping '{$post['title']}' (already exists)\n";
        continue;
    }

    // Stagger dates so posts aren't all the same day
    $daysAgo = ($i * 5) + 2; // 2, 7, 12, 17, ... days ago
    $createdAt = date('Y-m-d H:i:s', strtotime("-{$daysAgo} days"));

    blog_db_query(
        "INSERT INTO blog_posts (title, slug, excerpt, content, author, status, created_at, updated_at)
         VALUES (:title, :slug, :excerpt, :content, :author, 'published', :created_at, :created_at)",
        [
            'title' => $post['title'],
            'slug' => $post['slug'],
            'excerpt' => $post['excerpt'],
            'content' => $post['content'],
            'author' => $post['author'],
            'created_at' => $createdAt
        ]
    );
    $count++;
    echo "Created: {$post['title']}\n";
}

echo "\nDone! {$count} blog posts seeded.\n";
